  function buildPieceGeometry(piece) {
    const built = piece.polygons ? buildMultiPolygonPiece(piece) : piece.band ? buildBandPiece(piece) : piece.polar ? buildPolarPiece(piece) : buildPolygonPiece(piece);
    if (piece.plain) {
      // 纯色片（河流 / 洋流 / 海域 / 环带 / 点位）不参与地形明暗：
      // 顶点色一律压成 1，片就是片本身那块颜色。否则海底晕渲会把整片海域
      // 乘成一块深浅不匀的暗斑，远看像旧地图上的污渍。
      const col = built.surface.getAttribute("color");
      if (col) {
        for (let i2 = 0; i2 < col.array.length; i2++) col.array[i2] = 1;
        col.needsUpdate = true;
      }
    } else {
      // 拼片表面也要方向光晕渲：此前只有海拔灰度，同一座山南北坡一个色，
      // 加上 0.25° DEM 的细尺度坡向后，陆地才有真正的棱线与背光面。
      // base 取白：顶点色只当明暗乘子，片本身的配色（按模式）仍然透出来。
      // 逐像素明暗由 reliefTexture() 承担；顶点色只补一层很轻的宏观明暗，
      // 免得顶点级别的粗晕渲把贴图细节压掉。
      reliefShade(built.surface, {
        base: 0xffffff,
        exaggeration: 26,
        min: 0.86,
        max: 1.04,
        sample: 1.6,
        sample2: 0,
        snow: false,
        gain: 1.0
      });
    }
    const c2 = piece.center || [0, 0];
    return {
      surface: built.surface,
      side: built.side,
      rings: built.rings || [],
      centroid: unitAt(c2[0], c2[1]),
      triangles: built.surface.index.count / 3
    };
  }
  function buildOutline(pieces) {
    const positions = [];
    for (const p2 of pieces) {
      const built = p2._geo;
      if (!built || !built.rings) continue;
      for (const ring of built.rings) {
        if (!ring || ring.length < 2) continue;
        for (let i2 = 0; i2 < ring.length; i2++) {
          const a2 = ring[i2], b2 = ring[(i2 + 1) % ring.length];
          if (Math.abs(b2[0] - a2[0]) > 180) continue;
          const span = Math.max(Math.abs(b2[0] - a2[0]), Math.abs(b2[1] - a2[1]));
          const seg = Math.max(1, Math.min(40, Math.ceil(span / 3)));
          for (let s2 = 0; s2 < seg; s2++) {
            const t0 = s2 / seg, t1 = (s2 + 1) / seg;
            const l0 = a2[0] + (b2[0] - a2[0]) * t0, la0 = a2[1] + (b2[1] - a2[1]) * t0;
            const l1 = a2[0] + (b2[0] - a2[0]) * t1, la1 = a2[1] + (b2[1] - a2[1]) * t1;
            const pad = 0.012;
            const p0 = lonLatToVec3(l0, la0, surfaceRadius(l0, la0) + pad);
            const p1 = lonLatToVec3(l1, la1, surfaceRadius(l1, la1) + pad);
            positions.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
          }
        }
      }
    }
    const g2 = new As();
    g2.setAttribute("position", new vs(positions, 3));
    return g2;
  }
  function buildBoundaryLines(boundaries, radius) {
    const positions = [];
    const r2 = radius == null ? GEO.oceanR + 0.018 : radius;
    for (const item of boundaries || []) {
      for (const line of item.lines || []) {
        for (let i2 = 0; i2 < line.length - 1; i2++) {
          const a2 = line[i2], b2 = line[i2 + 1];
          const span = Math.max(Math.abs(b2[0] - a2[0]), Math.abs(b2[1] - a2[1]));
          const seg = Math.max(1, Math.min(24, Math.ceil(span / 1.5)));
          for (let s2 = 0; s2 < seg; s2++) {
            const t0 = s2 / seg, t1 = (s2 + 1) / seg;
            const l0 = a2[0] + (b2[0] - a2[0]) * t0, la0 = a2[1] + (b2[1] - a2[1]) * t0;
            const l1 = a2[0] + (b2[0] - a2[0]) * t1, la1 = a2[1] + (b2[1] - a2[1]) * t1;
            const p0 = lonLatToVec3(l0, la0, r2), p1 = lonLatToVec3(l1, la1, r2);
            positions.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z);
          }
        }
      }
    }
    const g2 = new As();
    g2.setAttribute("position", new vs(positions, 3));
    return g2;
  }
  function buildGraticule(radius) {
    const positions = [];
    const pushLine = (a2, b2) => {
      positions.push(a2.x, a2.y, a2.z, b2.x, b2.y, b2.z);
    };
    for (let lat = -60; lat <= 60; lat += 30) {
      for (let lon = -180; lon < 180; lon += 5) {
        pushLine(lonLatToVec3(lon, lat, radius), lonLatToVec3(lon + 5, lat, radius));
      }
    }
    for (let lon = -180; lon < 180; lon += 30) {
      for (let lat = -85; lat < 85; lat += 5) {
        pushLine(lonLatToVec3(lon, lat, radius), lonLatToVec3(lon, lat + 5, radius));
      }
    }
    const g2 = new As();
    g2.setAttribute("position", new vs(positions, 3));
    return g2;
  }

