        side.userData.pieceId = data.id;
        group.add(surface, side);
        group.userData.pieceId = data.id;
        this.trayGroup.add(group);
        const p2 = {
          data,
          geo,
          group,
          surface,
          side,
          index: i2,
          locked: false,
          centroid: geo.centroid,
          trayPos: new Ui()
        };
        // 拼片名称标签：挂在片的中心点上方，随片一起转、跟随托盘缩放；
        // 宽度按拼片角尺寸缩放（亚洲大、日本小），默认隐藏，由「拼片名称」开关控制。
        const cl2 = data.center || [0, 0];
