      const q2 = new Ii().setFromUnitVectors(p2.centroid, new Ui(0, 0, 1));
      q2.multiply(new Ii().setFromAxisAngle(new Ui(0, 1, 0), -0.22));
      q2.multiply(new Ii().setFromAxisAngle(new Ui(1, 0, 0), -0.12));
