        if (p2._flashTimer) { clearTimeout(p2._flashTimer); p2._flashTimer = null; }
        // 先只记下按下点：真的拖起来才把片挂到球面坐标系并跟随光标，
        // 否则「点一下看属性」会把托盘里的片抓走、射线也就打不中了。
        this.dragging = { piece: p2, q: new Ii(), angle: 180, start: [e2.clientX, e2.clientY], moved: false };
        this.canvas.style.cursor = "grabbing";
